mapper.update:

	  SELECT NVL(MAX(CERT_NO), 0) + 1
	  FROM TC_CERTS

MERGE INTO TC_CERTS c
USING DUAL ON (c.MEMBER_ID = #{memberId})

WHEN MATCHED THEN
	UPDATE
	SET ORIGINALFILE_NAME = #{originalfileName}
    	, SAVEFILE_NAME = #{savefileName}
		, UPDATE_DATE = SYSDATE
		, CERT_STAT = 'A701'

WHEN NOT MATCHED THEN
	INSERT(
		CERT_NO
		, MEMBER_ID
		, ORIGINALFILE_NAME
		, SAVEFILE_NAME
	)
	VALUES(
		#{certNo}
		, #{memberId}
		, #{originalfileName}
		, #{savefileName}
	)

UPDATE TC_CERTS

	UPDATE_DATE = SYSDATE
	, CERT_STAT = #{certStat}

		, CMT = #{cmt}


WHERE MEMBER_ID = #{memberId}
